INSERT INTO "knowledge_documents" ("id", "title", "category", "content", "status", "version", "metadata", "valid_until", "created_at", "updated_at") VALUES
('kb-backup-app-bbnet-sac', 'Aplicativo BBNET SAC: como entrar (login e senha) e para que serve', 'Atendimento', 'A BBNET tem o aplicativo BBNET SAC, gratuito, para celular Android e iPhone: é só procurar por BBNET SAC na loja de aplicativos do celular. Pelo aplicativo o cliente paga a fatura pelo PIX e tem acesso a outros serviços da BBNET. Para entrar, o login e a senha são os dois o CPF do titular do contrato, só os números, sem pontos e sem hífen. Se não conseguir entrar, confira se está usando o CPF de quem é o titular da internet; se mesmo assim não entrar, um atendente confere o cadastro.', 'published', 1, '{"origem":"backup-itabaiana","revisar":true}'::jsonb, NULL, '2026-11-24T22:00:00.000Z', '2026-11-24T22:00:00.000Z'),
('kb-backup-pix-copia-e-cola', 'Como pagar com o código PIX copia e cola', 'Financeiro', 'O código PIX copia e cola não é um link: é um texto grande que começa com 000201. Para pagar: toque e segure a mensagem que tem só o código, escolha Copiar, abra o aplicativo do seu banco, entre em Pix, escolha Pix Copia e Cola e cole o código. Confira o valor e confirme o pagamento. Pagando pelo PIX, a baixa é automática: se a internet estava bloqueada, ela volta em poucos minutos. Se depois do pagamento a internet não voltar, tire os aparelhos da tomada, espere alguns segundos e coloque de novo, sem apertar nenhum botão.', 'published', 1, '{"origem":"backup-itabaiana","revisar":true}'::jsonb, NULL, '2026-11-24T22:00:00.000Z', '2026-11-24T22:00:00.000Z')
ON CONFLICT ("id") DO NOTHING;
